return [
  {
    json: {
      dry_run: false,
      limit: 10,
      profile: 'feminino',
      marketplace: 'shopee',
      target: 'grupo-ofertas-feminino',
      target_chat_id: '120363412864266334@g.us',
      allowed_targets_csv: 'grupo-ofertas-feminino',
      channel_adapter: 'whatsapp',
      send_delay_seconds_min: 45,
      send_delay_seconds_max: 90,
      coupon_url: 'https://s.shopee.com.br/4AxtmHq4If',
      run_id: new Date().toISOString().replace(/[:.]/g, '-').slice(0, 19) + '-schedule-grupo-real',
    },
  },
];

return items.map((item, index) => ({
  json: {
    ...item.json,
    manifest_item_number: item.json.manifest_item_number ?? item.json.daily_sequence ?? index + 1,
    send_sequence_number: item.json.send_sequence_number ?? item.json.slot_sequence ?? index + 1,
  },
}));

const context = $('Validar Contexto').first().json;
const formatMoney = (value) => {
  if (value === null || value === undefined || value === '') return 'nao informado';
  const numberValue = Number(value);
  if (Number.isFinite(numberValue)) return `R$ ${numberValue.toFixed(2).replace('.', ',')}`;
  return String(value);
};
const formatMarketplace = (value) => {
  const normalized = String(value || '').trim().toLowerCase();
  if (normalized === 'shopee') return 'Shopee';
  return String(value || 'Marketplace').trim();
};
const discountPercent = (price, referencePrice) => {
  const current = Number(price);
  const reference = Number(referencePrice);
  if (!Number.isFinite(current) || !Number.isFinite(reference) || reference <= current || reference <= 0) return 0;
  return Math.round(((reference - current) / reference) * 100);
};
const formatRating = (value) => {
  const rating = Number(value);
  if (Number.isFinite(rating)) return rating.toFixed(1).replace('.', ',');
  return 'nao informada';
};
return items.map((item, index) => {
  const offer = item.json;
  const discount = discountPercent(offer.price, offer.reference_price);
  const messageText = `\u{1F525} ${offer.product_name}\n\n\u{1F4B5} ${formatMoney(offer.price)}\n\u{1F3F7}\u{FE0F} ${discount}% OFF\n\u{2B50} Avalia\u{00E7}\u{00E3}o: ${formatRating(offer.rating)}/5\n\u{2705} Link do produto:\n${offer.offer_link}\n\n\u{1F3EA} Loja: ${formatMarketplace(offer.marketplace)}\n\u{1F39F}\u{FE0F} Resgate o cupom desta p\u{00E1}gina:\n${context.coupon_url}\n(an\u{00FA}ncio)`;
  return {
    json: {
      ...context,
      ...offer,
      coupon_url: context.coupon_url,
      discount_percent: discount,
      manifest_item_number: offer.manifest_item_number ?? index + 1,
      send_sequence_number: offer.send_sequence_number ?? offer.manifest_item_number ?? index + 1,
      message_text: messageText,
      manifest_created_at: new Date().toISOString(),
    }
  };
});

const item = $json;
const allowed = new Set(item.allowed_targets || []);
const targetAllowed = allowed.has(item.target);
const blockedReason = targetAllowed ? null : 'target_not_allowlisted';
const deliveryStatus = targetAllowed ? (item.dry_run ? 'cancelled' : 'confirmed') : 'cancelled';
return { json: { ...item, target_allowed: targetAllowed, blocked_reason: blockedReason, delivery_status: deliveryStatus } };

const item = $json;
const sqlText = (value) => value === null || value === undefined ? 'null' : `'${String(value).replace(/'/g, "''")}'`;
const sqlNumber = (value) => value === null || value === undefined || value === '' || Number.isNaN(Number(value)) ? 'null' : String(Number(value));
const sqlJson = (value) => `${sqlText(JSON.stringify(value))}::jsonb`;
const payload = { run_id: item.run_id, dry_run: item.dry_run, target_allowed: item.target_allowed, blocked_reason: item.blocked_reason, send_result: item.send_result, score_reasons: item.score_reasons, rank_profile: item.rank_profile, rank_subniche: item.rank_subniche, coupon_url: item.coupon_url, discount_percent: item.discount_percent, image_url: item.image_url, waha_image_url: item.waha_image_url, adapter_status: item.adapter_status, adapter_message_id: item.adapter_message_id, adapter_ack: item.adapter_ack, adapter_response_type: item.adapter_response_type, send_sequence_number: item.send_sequence_number, waha_send_delay_seconds: item.waha_send_delay_seconds, send_delay_seconds_min: item.send_delay_seconds_min, send_delay_seconds_max: item.send_delay_seconds_max, dispatch_plan_id: item.dispatch_plan_id, planned_hour: item.planned_hour, slot_sequence: item.slot_sequence, daily_sequence: item.daily_sequence, selection_bucket: item.selection_bucket, selection_reason: item.selection_reason };
const upsertQuery = `insert into offers.publication_events (dispatch_plan_id, profile, marketplace, stable_key, item_id, target, channel_adapter, delivery_status, manifest_item_number, artifact_generated_at, manifest_created_at, planned_at, sent_at, offer_title, offer_url, offer_price, message_text, payload) values (${sqlText(item.dispatch_plan_id)}::uuid, ${sqlText(item.profile)}, ${sqlText(item.marketplace)}, ${sqlText(item.stable_key)}, ${sqlNumber(item.item_id)}, ${sqlText(item.target)}, ${sqlText(item.channel_adapter)}, ${sqlText(item.delivery_status)}, ${sqlNumber(item.manifest_item_number)}, ${sqlText(item.artifact_generated_at)}::timestamptz, ${sqlText(item.manifest_created_at)}::timestamptz, ${sqlText(item.planned_at)}::timestamptz, ${sqlText(item.sent_at)}::timestamptz, ${sqlText(item.product_name)}, ${sqlText(item.offer_link)}, ${sqlNumber(item.price)}, ${sqlText(item.message_text)}, ${sqlJson(payload)}) on conflict (dispatch_plan_id) where dispatch_plan_id is not null do update set delivery_status = excluded.delivery_status, sent_at = excluded.sent_at, message_text = excluded.message_text, payload = excluded.payload, updated_at = now() returning publish_id;`;
return { json: { ...item, publication_event_upsert_query: upsertQuery } };

const item = items[0].json;
const cleanText = (value, field) => { const text = String(value || '').trim(); if (!/^[a-z0-9][a-z0-9_-]{1,80}$/i.test(text)) throw new Error(`${field} fora do contrato MVP: ${text}`); return text; };
const parseDelay = (value, field, fallback) => { const numeric = Number(value ?? fallback); if (!Number.isInteger(numeric) || numeric < 0 || numeric > 600) throw new Error(`${field} fora do contrato MVP: ${value}`); return numeric; };
const profile = cleanText(item.profile, 'profile');
const marketplace = cleanText(item.marketplace, 'marketplace');
const target = cleanText(item.target, 'target');
const channelAdapter = cleanText(item.channel_adapter, 'channel_adapter');
const limit = Number(item.limit || 1);
if (!Number.isInteger(limit) || limit < 1 || limit > 20) throw new Error(`limit fora do contrato MVP: ${item.limit}`);
const dryRun = item.dry_run === true || item.dry_run === 'true' || item.dry_run === 1 || item.dry_run === '1';
const allowedTargets = String(item.allowed_targets_csv || '').split(',').map((targetItem) => targetItem.trim()).filter(Boolean);
if (allowedTargets.length === 0) throw new Error('allowed_targets_csv obrigatorio');
const sendDelaySecondsMin = parseDelay(item.send_delay_seconds_min, 'send_delay_seconds_min', 45);
const sendDelaySecondsMax = parseDelay(item.send_delay_seconds_max, 'send_delay_seconds_max', 90);
if (sendDelaySecondsMax < sendDelaySecondsMin) throw new Error('send_delay_seconds_max deve ser maior ou igual a send_delay_seconds_min');
const artifactGeneratedAt = item.artifact_generated_at || new Date().toISOString();
const claimToken = cleanText(item.run_id, 'run_id');
const sqlText = (value) => `'${String(value).replace(/'/g, "''")}'`;
const previewQuery = `select null::uuid as dispatch_plan_id, ready.profile, ready.marketplace, ready.stable_key, ready.item_id, ready.product_name, ready.offer_link, ready.image_url, ready.price, ready.reference_price, ready.rating, ready.sales_count, ready.primary_subniche, ready.commercial_score, ready.score_reasons, ready.rank_profile, ready.rank_subniche, ready.selection_bucket, ready.selection_reason, ready.planned_date, ready.planned_hour, ready.slot_sequence, ready.daily_sequence, ready.planned_at from offers.v_daily_dispatch_ready ready where ready.is_ready_for_dispatch and ready.profile = ${sqlText(profile)} and ready.marketplace = ${sqlText(marketplace)} and ready.planned_date = (now() at time zone 'America/Sao_Paulo')::date and ready.planned_hour = extract(hour from now() at time zone 'America/Sao_Paulo')::integer order by ready.slot_sequence limit ${limit};`;
const claimQuery = `with next_slots as (select plan.dispatch_plan_id from offers.daily_dispatch_plan plan join offers.v_daily_dispatch_ready ready using (dispatch_plan_id) where ready.is_ready_for_dispatch and ready.profile = ${sqlText(profile)} and ready.marketplace = ${sqlText(marketplace)} and ready.planned_date = (now() at time zone 'America/Sao_Paulo')::date and ready.planned_hour = extract(hour from now() at time zone 'America/Sao_Paulo')::integer order by ready.slot_sequence for update of plan skip locked limit ${limit}), claimed as (update offers.daily_dispatch_plan plan set dispatch_status = 'claimed', claim_token = ${sqlText(claimToken)}, claimed_at = now(), updated_at = now() from next_slots where plan.dispatch_plan_id = next_slots.dispatch_plan_id returning plan.dispatch_plan_id) select ready.dispatch_plan_id, ready.profile, ready.marketplace, ready.stable_key, ready.item_id, ready.product_name, ready.offer_link, ready.image_url, ready.price, ready.reference_price, ready.rating, ready.sales_count, ready.primary_subniche, ready.commercial_score, ready.score_reasons, ready.rank_profile, ready.rank_subniche, ready.selection_bucket, ready.selection_reason, ready.planned_date, ready.planned_hour, ready.slot_sequence, ready.daily_sequence, ready.planned_at from claimed join offers.v_daily_dispatch_ready ready using (dispatch_plan_id) order by ready.slot_sequence;`;
const rankingQuery = dryRun ? previewQuery : claimQuery;
return [{ json: { ...item, profile, marketplace, target, channel_adapter: channelAdapter, limit, dry_run: dryRun, allowed_targets: allowedTargets, send_delay_seconds_min: sendDelaySecondsMin, send_delay_seconds_max: sendDelaySecondsMax, artifact_generated_at: artifactGeneratedAt, run_id: claimToken, ranking_query: rankingQuery } }];

const item = $json;
const shouldSend = item.channel_adapter === 'whatsapp' && item.target_allowed === true && item.dry_run === false && item.send_result === 'ready_for_real_channel_node';
const normalizeChatId = (value) => { const raw = String(value || '').trim(); if (!raw) return null; if (raw.endsWith('@c.us') || raw.endsWith('@g.us') || raw.endsWith('@lid')) return raw; const digits = raw.replace(/[^\d]/g, ''); if (digits.length >= 12 && digits.length <= 15) return `${digits}@c.us`; return null; };
const normalizeImageUrl = (value) => { const raw = String(value || '').trim(); if (!raw || !/^https?:\/\//i.test(raw)) return null; return raw; };
const filenameFrom = (value) => { const suffix = String(value || 'oferta').replace(/[^a-z0-9_-]/gi, '').slice(0, 80) || 'oferta'; return `oferta-${suffix}.jpg`; };
const normalizeDelay = (value, fallback) => { const numeric = Number(value ?? fallback); return Number.isFinite(numeric) && numeric >= 0 ? Math.floor(numeric) : fallback; };
const randomDelay = (minValue, maxValue) => maxValue <= minValue ? minValue : Math.floor(Math.random() * (maxValue - minValue + 1)) + minValue;
const sequenceNumber = Number(item.send_sequence_number || item.manifest_item_number || 1);
const delayMin = normalizeDelay(item.send_delay_seconds_min, 45);
const delayMax = Math.max(delayMin, normalizeDelay(item.send_delay_seconds_max, 90));
const waitSeconds = shouldSend && sequenceNumber > 1 ? randomDelay(delayMin, delayMax) : 0;
const wahaChatId = normalizeChatId(item.target_chat_id || item.target);
const wahaImageUrl = normalizeImageUrl(item.image_url);
if (shouldSend && !wahaChatId) return { json: { ...item, waha_should_send: false, waha_chat_id: null, waha_image_url: wahaImageUrl, waha_send_delay_seconds: 0, adapter_status: 'adapter_missing_chat_id', send_result: 'adapter_missing_chat_id', delivery_status: 'failed', sent_at: null } };
if (shouldSend && !wahaImageUrl) return { json: { ...item, waha_should_send: false, waha_chat_id: wahaChatId, waha_image_url: null, waha_send_delay_seconds: 0, adapter_status: 'adapter_missing_image_url', send_result: 'adapter_missing_image_url', delivery_status: 'failed', sent_at: null } };
return { json: { ...item, waha_should_send: shouldSend, waha_chat_id: shouldSend ? wahaChatId : null, waha_image_url: shouldSend ? wahaImageUrl : null, waha_image_filename: shouldSend ? filenameFrom(item.item_id || item.stable_key) : null, waha_send_delay_seconds: waitSeconds } };
